const _ = require('lodash');
const users = [{ id: 2, name: "b", role: "admin" }, { id: 1, name: "a", role: "user" }, { id: 3, name: "c", role: "admin" }];
test("collections", () => {
  expect(_.map(users, "name")).to.eql(["b", "a", "c"]);
  expect(_.filter(users, { role: "admin" }).length).to.equal(2);
  expect(_.find(users, (u) => u.id === 1).name).to.equal("a");
  expect(_.sortBy(users, "id").map((u) => u.id)).to.eql([1, 2, 3]);
  expect(_.orderBy(users, ["id"], ["desc"])[0].id).to.equal(3);
  expect(Object.keys(_.groupBy(users, "role"))).to.eql(["admin", "user"]);
  expect(_.keyBy(users, "id")[3].name).to.equal("c");
  expect(_.sumBy(users, "id")).to.equal(6);
  expect(_.uniq([1, 1, 2])).to.eql([1, 2]);
  expect(_.chunk([1, 2, 3], 2)).to.eql([[1, 2], [3]]);
  expect(_.flattenDeep([1, [2, [3]]])).to.eql([1, 2, 3]);
  expect(_.range(3)).to.eql([0, 1, 2]);
});
test("objects", () => {
  const o = { a: { b: [{ c: 1 }] } };
  expect(_.get(o, "a.b[0].c")).to.equal(1);
  expect(_.get(o, "a.x", "d")).to.equal("d");
  expect(_.has(o, "a.b")).to.be.true;
  expect(_.set({}, "x.y", 2)).to.eql({ x: { y: 2 } });
  expect(_.pick({ a: 1, b: 2 }, "a")).to.eql({ a: 1 });
  expect(_.omit({ a: 1, b: 2 }, ["a"])).to.eql({ b: 2 });
  expect(_.merge({ a: { x: 1 } }, { a: { y: 2 } })).to.eql({ a: { x: 1, y: 2 } });
  const deep = _.cloneDeep(o);
  deep.a.b[0].c = 9;
  expect(o.a.b[0].c).to.equal(1);
  expect(_.isEqual({ a: [1, { b: 2 }] }, { a: [1, { b: 2 }] })).to.be.true;
  expect(_.isEmpty({})).to.be.true;
  expect(_.isEmpty([1])).to.be.false;
});
test("strings", () => {
  expect(_.camelCase("Foo Bar")).to.equal("fooBar");
  expect(_.snakeCase("fooBar")).to.equal("foo_bar");
  expect(_.kebabCase("Foo Bar")).to.equal("foo-bar");
  expect(_.capitalize("hELLO")).to.equal("Hello");
  expect(_.padStart("5", 3, "0")).to.equal("005");
});
